 "research_question": "Is a defense's effect on the opponent's second-half offensive performance relative to their first-half performance a reliable and consistent team trait?",
 "retrieval_summary": {
  "prior_findings": [],
  "failed_experiments": [],
  "limitations": [],
  "unresolved": []
